CREATE DATABASE IF NOT EXISTS classmanager CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE classmanager;

CREATE TABLE gestores (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE professores (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, especialidade VARCHAR(120) NOT NULL, carga_horaria TINYINT UNSIGNED NOT NULL, status ENUM('ativo','inativo') NOT NULL DEFAULT 'ativo',
 telefone VARCHAR(30), cpf VARCHAR(20), data_nascimento DATE, endereco VARCHAR(255), formacao VARCHAR(255), registro_profissional VARCHAR(100), documentos_comprovacao TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE horarios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, turma VARCHAR(120) NOT NULL, professor_id INT UNSIGNED NOT NULL, dia_semana ENUM('Seg','Ter','Qua','Qui','Sex','Sab') NOT NULL, hora_inicio TIME NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (professor_id) REFERENCES professores(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE alunos (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, nivel ENUM('Iniciante','Básico','Intermediário','Avançado') NOT NULL, status ENUM('ativo','inativo','trancado') NOT NULL DEFAULT 'ativo', horario_id INT UNSIGNED NULL,
 telefone VARCHAR(30), cpf VARCHAR(20), data_nascimento DATE, endereco VARCHAR(255), responsavel_nome VARCHAR(120), responsavel_telefone VARCHAR(30), data_matricula DATE NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (horario_id) REFERENCES horarios(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE frequencias (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, aluno_id INT UNSIGNED NOT NULL, horario_id INT UNSIGNED NOT NULL, data_aula DATE NOT NULL, presente TINYINT(1) NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY frequencia_unica (aluno_id, horario_id, data_aula), FOREIGN KEY (aluno_id) REFERENCES alunos(id) ON DELETE CASCADE, FOREIGN KEY (horario_id) REFERENCES horarios(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE notas (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, aluno_id INT UNSIGNED NOT NULL, horario_id INT UNSIGNED NOT NULL, avaliacao VARCHAR(120) NOT NULL, nota DECIMAL(5,2) NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (aluno_id) REFERENCES alunos(id) ON DELETE CASCADE, FOREIGN KEY (horario_id) REFERENCES horarios(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE codigos_recuperacao (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tipo ENUM('aluno','professor','gestor') NOT NULL, usuario_id INT UNSIGNED NOT NULL, codigo_hash VARCHAR(255) NOT NULL, expira_em DATETIME NOT NULL, usado_em DATETIME NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (tipo, usuario_id)) ENGINE=InnoDB;

